  'backhaul.heading': { ru: 'Обратный груз из {state} — кому звонить', en: 'Backhaul from {state} — who to call', es: 'Carga de regreso desde {state}: a quién llamar', uk: 'Зворотний вантаж із {state} — кому дзвонити', ro: 'Cursă de întoarcere din {state} — pe cine suni', kk: '{state} штатынан кері жүк — кімге қоңырау шалу' },
  'backhaul.info': { ru: 'Свои брокеры, которые уже давали грузы из штата выгрузки: телефон, средняя ставка, сколько раз возили и как платят. Считается по вашей истории грузов.', en: 'Your brokers who already gave loads out of the delivery state: phone, average rate, how many times and how they pay. Built from your own load history.', es: 'Tus brókers que ya dieron cargas desde el estado de entrega: teléfono, tarifa media, cuántas veces y cómo pagan. Según tu historial.', uk: 'Свої брокери, які вже давали вантажі зі штату вивантаження: телефон, середня ставка, скільки разів возили і як платять. За вашою історією.', ro: 'Brokerii tăi care au dat deja curse din statul de livrare: telefon, tarif mediu, de câte ori și cum plătesc. Din istoricul tău.', kk: 'Түсіру штатынан жүк берген өз брокерлерің: телефон, орташа ставка, неше рет және қалай төлейді. Өз тарихың бойынша.' },
  'backhaul.stats': { ru: '{n} рейс(ов) отсюда · ср. {rate} · {rpm}/mi', en: '{n} load(s) from here · avg {rate} · {rpm}/mi', es: '{n} carga(s) desde aquí · media {rate} · {rpm}/mi', uk: '{n} рейс(ів) звідси · сер. {rate} · {rpm}/mi', ro: '{n} curse de aici · mediu {rate} · {rpm}/mi', kk: 'осы жерден {n} рейс · орташа {rate} · {rpm}/mi' },
