  'rcDrop.title': { ru: 'Создать груз из Rate con', en: 'Create a load from a rate con', es: 'Crear una carga desde el rate con', uk: 'Створити вантаж із Rate con', ro: 'Creează o cursă din rate con', kk: 'Rate con-нан жүк құру' },
  'rcDrop.explain': { ru: 'Загрузи PDF или фото рейт-кона — ИИ прочитает его, создаст груз на этот трак, подошьёт документ и покажет, что проверить. Driver Info можно загрузить вместе с ним.', en: 'Upload the rate con as a PDF or photo — AI reads it, creates the load on this truck, files the document and shows what to check. You can upload the Driver Info sheet along with it.', es: 'Sube el rate con en PDF o foto: la IA lo lee, crea la carga en este camión, archiva el documento y muestra qué revisar. Puedes subir la hoja Driver Info junto con él.', uk: 'Завантаж PDF або фото рейт-кона — ШІ прочитає його, створить вантаж на цей трак, підшиє документ і покаже, що перевірити. Driver Info можна завантажити разом.', ro: 'Încarcă rate con-ul ca PDF sau poză — AI-ul îl citește, creează cursa pe acest camion, atașează documentul și arată ce trebuie verificat. Fișa Driver Info poate fi încărcată împreună cu el.', kk: 'Rate con-ды PDF немесе фото түрінде жүкте — ЖИ оны оқып, осы тракқа жүк құрады, құжатты тіркеп, нені тексеру керектігін көрсетеді. Driver Info парағын онымен бірге жүктеуге болады.' },
  'rcDrop.chooseFile': { ru: 'Выбрать файл', en: 'Choose file', es: 'Elegir archivo', uk: 'Вибрати файл', ro: 'Alege fișierul', kk: 'Файл таңдау' },
  'rcDrop.orDrop': { ru: 'или перетащи файлы сюда', en: 'or drag the files here', es: 'o arrastra los archivos aquí', uk: 'або перетягни файли сюди', ro: 'sau trage fișierele aici', kk: 'немесе файлдарды осында сүйре' },
  'rcDrop.dropCta': { ru: '＋ Rate con → сразу груз на этот трак', en: '＋ Rate con → an instant load on this truck', es: '＋ Rate con → carga instantánea en este camión', uk: '＋ Rate con → одразу вантаж на цей трак', ro: '＋ Rate con → cursă instant pe acest camion', kk: '＋ Rate con → осы трактқа бірден жүк' },
  'rcDrop.dropSubtext': { ru: 'PDF или фото. ИИ распознает, создаст груз и покажет, что проверить.', en: 'PDF or photo. AI reads it, creates the load, and shows what to check.', es: 'PDF o foto. La IA lo lee, crea la carga y muestra qué revisar.', uk: 'PDF або фото. ШІ розпізнає, створить вантаж і покаже, що перевірити.', ro: 'PDF sau poză. IA citește, creează cursa și arată ce trebuie verificat.', kk: 'PDF немесе сурет. ЖИ таниды, жүк құрады және нені тексеру керегін көрсетеді.' },
