  // lib/rc-warnings.ts
  'rcWarn.team': { ru: 'Требуется team (два водителя) — проверь, потянет ли один.', en: 'Team required (two drivers) — check whether a solo driver can cover it.', es: 'Se pide team (dos conductores) — comprueba si uno solo puede.', uk: 'Потрібен team (два водії) — перевір, чи потягне один.', ro: 'Se cere echipaj (doi șoferi) — verifică dacă unul singur face față.', kk: 'Team керек (екі жүргізуші) — біреуі шыдай ма, тексеріңіз.' },
  'rcWarn.hazmat': { ru: 'Hazmat / опасный груз — нужен эндорсмент и допуск.', en: 'Hazmat / dangerous goods — an endorsement and clearance are required.', es: 'Hazmat / mercancía peligrosa — hace falta endoso y permiso.', uk: 'Hazmat / небезпечний вантаж — потрібен ендорсмент і допуск.', ro: 'Hazmat / marfă periculoasă — e nevoie de andosare și permis.', kk: 'Hazmat / қауіпті жүк — эндорсмент пен рұқсат керек.' },
  'rcWarn.reefer': { ru: 'Рефрижератор / температурный режим — проверь настройку и pre-cool.', en: 'Reefer / temperature-controlled — check the setpoint and pre-cool.', es: 'Refrigerado / temperatura — revisa el ajuste y el pre-cool.', uk: 'Рефрижератор / температурний режим — перевір налаштування і pre-cool.', ro: 'Frigorific / regim de temperatură — verifică setarea și pre-cool-ul.', kk: 'Рефрижератор / температура режимі — баптау мен pre-cool тексеріңіз.' },
  'rcWarn.detention': { ru: 'Указан detention — зафиксируй время in/out, уточни ставку ожидания.', en: 'Detention is mentioned — log the in/out times and confirm the waiting rate.', es: 'Se menciona detención — anota la hora de entrada/salida y confirma la tarifa de espera.', uk: 'Вказано detention — зафіксуй час in/out, уточни ставку очікування.', ro: 'Se menționează detenția — notează ora in/out și confirmă tariful de așteptare.', kk: 'Detention көрсетілген — in/out уақытын жазып, күту мөлшерлемесін нақтылаңыз.' },
  'rcWarn.lumper': { ru: 'Lumper (платная разгрузка) — сохрани чек, добавь в инвойс возмещением.', en: 'Lumper (paid unloading) — keep the receipt and add it to the invoice as a reimbursement.', es: 'Lumper (descarga pagada) — guarda el recibo y ponlo en la factura como reembolso.', uk: 'Lumper (платне розвантаження) — збережи чек, додай в інвойс відшкодуванням.', ro: 'Lumper (descărcare plătită) — păstrează bonul și pune-l pe factură ca rambursare.', kk: 'Lumper (ақылы түсіру) — чекті сақтаңыз, инвойсқа өтемақы ретінде қосыңыз.' },
  'rcWarn.tonu': { ru: 'Есть условие TONU — если груз отменят, потребуй оплату за подачу.', en: 'A TONU clause is present — if the load is cancelled, demand payment for the trip.', es: 'Hay cláusula TONU — si cancelan la carga, exige el pago por el traslado.', uk: 'Є умова TONU — якщо вантаж скасують, вимагай оплату за подачу.', ro: 'Există clauză TONU — dacă se anulează cursa, cere plata pentru deplasare.', kk: 'TONU шарты бар — жүк тоқтатылса, келу үшін төлемді талап етіңіз.' },
  'rcWarn.appointment': { ru: 'Загрузка/выгрузка строго по записи (appointment) — опоздание = проблемы.', en: 'Pickup/delivery is a strict appointment — being late means trouble.', es: 'Carga/descarga estrictamente con cita — llegar tarde da problemas.', uk: 'Завантаження/вивантаження строго за записом (appointment) — запізнення = проблеми.', ro: 'Încărcare/descărcare strict cu programare — întârzierea aduce probleme.', kk: 'Тиеу/түсіру қатаң жазылу бойынша (appointment) — кешігу = мәселе.' },
  'rcWarn.fcfs': { ru: 'FCFS (живая очередь) — заложи время на ожидание.', en: 'FCFS (first come, first served) — budget in wait time.', es: 'FCFS (por orden de llegada) — cuenta con tiempo de espera.', uk: 'FCFS (жива черга) — заклади час на очікування.', ro: 'FCFS (primul venit, primul servit) — pune la socoteală timp de așteptare.', kk: 'FCFS (кезек) — күтуге уақыт жоспарлаңыз.' },
  'rcWarn.driverAssist': { ru: 'Возможна разгрузка/погрузка силами водителя — уточни заранее.', en: 'The driver may need to help load/unload — confirm ahead of time.', es: 'Puede que el conductor tenga que ayudar a cargar/descargar — confírmalo antes.', uk: 'Можливе розвантаження/завантаження силами водія — уточни заздалегідь.', ro: 'Șoferul ar putea trebui să ajute la încărcare/descărcare — confirmă din timp.', kk: 'Жүргізушінің күшімен тиеу/түсіру болуы мүмкін — алдын ала нақтылаңыз.' },
  'rcWarn.palletExchange': { ru: 'Обмен паллет / pallet jack — уточни условия.', en: 'Pallet exchange / pallet jack — confirm the terms.', es: 'Intercambio de palés / transpaleta — confirma las condiciones.', uk: 'Обмін палет / pallet jack — уточни умови.', ro: 'Schimb de paleți / transpalet — confirmă condițiile.', kk: 'Паллет алмасу / pallet jack — шарттарды нақтылаңыз.' },
